INSERT INTO health_profile (
    user_id, age, sex, height_cm, weight_kg, activity_level, goal, timezone,
    calorie_low, calorie_high, estimated, version_no, created_at, updated_at
) VALUES (
    #{userId}, #{age}, #{sex}, #{heightCm}, #{weightKg}, #{activityLevel}, #{goal}, #{timezone},
    #{calorieLow}, #{calorieHigh}, #{estimated}, #{versionNo}, #{createdAt}, #{updatedAt}
)

INSERT INTO health_profile_version (
    user_id, profile_id, version_no, snapshot_json, calorie_low, calorie_high, created_at
) VALUES (
    #{userId}, #{profileId}, #{versionNo}, #{snapshotJson}, #{calorieLow}, #{calorieHigh}, #{createdAt}
)
